    /// Each fixture in `payload.invalid-examples.json` MUST be
    /// rejected by at least one of: serde deserialization, or
    /// JSON-Schema validation under the `validate` feature. The
    /// fixture file documents the producer-side bug class that
    /// each payload exemplifies; this generated test pins it.
    #[cfg(feature = "validate")]
    #[test]
    fn rejects_invalid_examples() {
        use crate::validate::ValidatedPayload;
        let fixtures: &[(&str, &str)] = &[
            (
                "Unknown top-level member — additionalProperties: false catches `services`. Selective reload is the member this task most invites and most deliberately excludes: it turns 'apply what is written down' into 'apply what this document says', which is a much wider authority than a reload should carry.",
                "{\n  \"services\": [\n    \"didcomm\"\n  ]\n}",
            ),
            (
                "Unknown top-level member — `force`. There is no validation to skip; a flag suggesting otherwise would be implemented by someone who did not check.",
                "{\n  \"force\": true\n}",
            ),
            (
                "Unknown top-level member — `config`. Inline configuration would let a producer put the agent into a state its own configuration does not describe, with no record of it anywhere but this request.",
                "{\n  \"config\": {\n    \"publicUrl\": \"https://elsewhere.example\"\n  }\n}",
            ),
            (
                "Bare/unnamespaced ext key — SPEC §4.5.1 requires every immediate child of ext to be reverse-DNS namespaced. Worth pinning on a payload whose only permitted member is ext.",
                "{\n  \"ext\": {\n    \"bare-key\": {\n      \"anything\": \"here\"\n    }\n  }\n}",
            ),
        ];
        for (i, (note, raw)) in fixtures.iter().enumerate() {
            let value: serde_json::Value = match serde_json::from_str(raw) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let serde_ok = serde_json::from_value::<super::Payload>(value.clone()).is_ok();
            let schema_ok = super::Payload::validate_value(&value).is_ok();
            assert!(
                !(serde_ok && schema_ok),
                "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
                i + 1,
                note,
                raw
            );
        }
    }
